from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
jobs=json.loads(Path('/Users/tidepool/Projects/goji-reel-animation/jobs.json').read_text())
style='One continuous original 2004 GTA San Andreas PS2 low-polygon gameplay shot, angular meshes and simple baked textures. Preserve the reference design, pale teal sky, green trees and consistent daylight. '
changes={
'02-takeover':(97,3.5,style+'The maroon woman yanks the taxi driver out through the OPEN front RIGHT door. She reaches her left arm in and grips his upper arm, pulls sharply backward, the driver stumbles out feet first, then rolls sideways harmlessly onto the road. She pivots into the now empty driver seat. One solid blue taxi remains parked and rigid throughout, NO body panels disappear, no cross dissolves, no mesh clipping. The front-hinged door stays attached to the A pillar. Follow the woman from behind. Driver remains conscious and unharmed, no blood.'),
'03-drive':(241,6.0,style+'FULL SPEED reckless arcade driving, violent acceleration, continuous rear chase camera tightly following the blue Comfort taxi. The taxi swerves sharply LEFT to overtake the silver sedan, steers hard RIGHT through a narrow gap beside the white van, then cuts LEFT across the red sedan. Three distinct fast lane changes. Other drivers react immediately: bright red brake lights, silver sedan brakes hard and swerves aside, white van veers right, red sedan fishtails slightly to avoid the taxi. Cars are passed rapidly and fall behind out of frame. Road markings race beneath the taxi, buildings and trees streak backward with strong parallax, tyres briefly smoke on each swerve, suspension rolls with steering. Increasing speed and near misses, GTA San Andreas mayhem. Camera rotates with taxi heading but always stays behind its trunk. Continuous forward progress at highway speed, not a stationary tableau. End with taxi veering left toward the Lentor Modern kerb. No collisions with people, no blood, no explosion, no slow motion, no camera orbit, no text or HUD.'),
'04-impact':(41,0.9,style+'Rear chase camera. Blue Comfort taxi accelerates forward over the kerb straight into the slender lamp post two metres ahead. Gap closes completely, bumper makes HARD CONTACT with pole, nose abruptly stops and rear suspension kicks upward briefly. Camera jolts violently at contact. Small compact dent in nose only, no growing crumple mass, rigid taxi body. Woman remains inside right driver seat until impact. Pedestrians on pavement flinch and begin jumping sideways away from trajectory. No blood, no explosion, no pedestrian contact.'),
'05-ejection':(57,1.4,style+'Rear gameplay camera following maroon woman who is ALREADY airborne in front of the stopped taxi, flying rapidly forward away from camera with black purse, descending toward pavement. Two adult passersby see her coming and immediately DIVE sideways away from her trajectory, one dives left with arms extended and rolls, the other jumps right and tumbles safely. Exaggerated GTA San Andreas NPC evasive dives, rapid slapstick motion. Taxi stays motionless with front bumper contacting lamp post, normal solid proportions. Woman lands in clear space and stumbles forward unhurt. No person emerges through roof, no blood, no injuries, no text.'),
'07-entry':(73,2.5,'A calm GTA San Andreas PS2 interior cutscene with fixed camera. Woman in maroon walks slowly to the burgundy Goji reception table. The navy-uniform Goji team member STAYS SEATED behind the table, smiles, gives a small friendly open-hand welcoming gesture, and nods to the arriving woman. Player relaxes her shoulders and returns a small nod. Preserve GOJI wall sign, table, chairs and checked floor. Warm quiet welcome after chaos. No music, no captions.'),
'08a-reformer':(121,5.0,'A calm fixed side-view GTA San Andreas PS2 cutscene, same low polygon characters and cream Goji reformer. Maintain the EXACT kneeling lunge pose: front left socked foot fixed on the small front platform, both hands fixed on padded footbar, rear right knee on sliding carriage. Female navy physiotherapist keeps both hands in CONTACT with the sides of the maroon player\'s pelvis. Therapist gently guides hips backward and forward through ONE small controlled stretch, slightly extending the rear hip then assisting return. Carriage translates only 5 centimetres horizontally along fixed rails with the rear knee, never rotates or rocks. Front platform, footbar, frame and floor are completely stationary. Therapist actively leans and presses gently with hands to support alignment, no passive observing. Slow breathing, relaxed expressions. No change of exercise, no extra limbs, no music, no text.'),
'08b-mat':(145,6.0,'A calm fixed camera GTA San Andreas PS2 interior cutscene. Maroon player sits cross-legged with both hips grounded, one palm planted and opposite arm overhead. Navy female physiotherapist kneels beside and behind, keeps one hand contacting the raised upper arm and other contacting side of waist. Therapist visibly assists a SLOW deeper side stretch: gently guides raised arm a little farther overhead while stabilising waist, holds for two seconds, then gently helps patient return a few centimetres. Therapist shifts body weight with the stretch and maintains both points of contact. Player breathes slowly, relaxed, no grimace. Burgundy mat stays flat, reformer background stationary. No exercise switching, no abrupt movement, no music or text.')}
for j in jobs:
 if j['name'] in changes:
  j['frames'],j['edit_duration'],j['prompt']=changes[j['name']]
  j['seed']+=100
  j['images']=[dict(path=str(R/'assets'/(j['name']+'.png')),frame=0,strength=1.0)]
(R/'jobs.json').write_text(json.dumps(jobs,indent=2))
